<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { cancelOrder, confirmOrder, listOrders, orderDetail, orderStatistics, readyOrder, rejectOrder } from '../../api/admin'
import type { Order, OrderDetail } from '../../api/types'
const rows = ref<Order[]>([]); const total = ref(0); const page = ref(1); const status = ref<number | undefined>(); const stats = ref({ toBeConfirmed: 0, making: 0, readyForPickup: 0 })
const drawer = ref(false); const detail = ref<(Order & { orderDetailList?: OrderDetail[] }) | null>(null); const detailLoading = ref(false)
const statusText: Record<number, string> = { 10: '待支付', 20: '待接单', 30: '制作中', 40: '待取餐', 50: '已取餐', 60: '已取消', 70: '已退款' }
const statusType: Record<number, string> = { 10: 'warning', 20: 'danger', 30: 'primary', 40: 'success', 50: 'success', 60: 'info', 70: 'info' }
async function load() { const data = await listOrders({ page: page.value, pageSize: 20, status: status.value }); rows.value = data.records || []; total.value = data.total; stats.value = await orderStatistics() }
async function showDetail(row: Order) { drawer.value = true; detailLoading.value = true; try { detail.value = await orderDetail(row.id) } catch (error) { ElMessage.error((error as Error).message) } finally { detailLoading.value = false } }
async function confirm(row: Order) { await confirmOrder(row.id); ElMessage.success('已接单，进入制作中'); await load() }
async function ready(row: Order) { await readyOrder(row.id); ElMessage.success('已出餐，等待学生取餐'); await load() }
async function cancel(row: Order) { try { const result = await ElMessageBox.prompt('请输入取消原因', '取消订单', { inputPlaceholder: row.status === 10 ? '例如：学生申请取消' : '例如：档口设备故障' }); await cancelOrder(row.id, result.value); ElMessage.success('订单已取消'); await load() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error instanceof Error ? error.message : '取消失败') } }
async function reject(row: Order) { try { const result = await ElMessageBox.prompt('请输入拒单原因，已支付订单将进入退款状态', '拒绝订单', { inputPlaceholder: '例如：食材售罄' }); await rejectOrder(row.id, result.value); ElMessage.success('订单已拒绝'); await load() } catch (error) { if (error !== 'cancel' && error !== 'close') ElMessage.error(error instanceof Error ? error.message : '拒单失败') } }
onMounted(load)
</script>
<template><div class="page-card"><div class="page-header"><div><h2 class="page-title">订单管理</h2><p class="page-subtitle">接单 → 制作中 → 待取餐 → 核销，所有动作由后端状态机校验。</p></div></div><div class="page-actionbar"><div class="query-area"><el-select v-model="status" clearable placeholder="全部状态" style="width:160px" @change="page=1;load()"><el-option v-for="(label, value) in statusText" :key="value" :label="label" :value="Number(value)" /></el-select><el-button @click="load">刷新</el-button></div><div class="action-area"><div class="order-stats"><span>待接单 <b>{{ stats.toBeConfirmed }}</b></span><span>制作中 <b>{{ stats.making }}</b></span><span>待取餐 <b>{{ stats.readyForPickup }}</b></span></div></div></div><el-table :data="rows" stripe><el-table-column prop="number" label="订单号" min-width="160" /><el-table-column prop="orderDishes" label="餐品" min-width="220" /><el-table-column prop="amount" label="金额" width="90"><template #default="{ row }">¥{{ row.amount }}</template></el-table-column><el-table-column prop="pickupCode" label="取餐码" width="90" /><el-table-column label="状态" width="95"><template #default="{ row }"><el-tag :type="statusType[row.status]">{{ statusText[row.status] }}</el-tag></template></el-table-column><el-table-column prop="orderTime" label="下单时间" width="165" /><el-table-column label="操作" align="center" header-align="center" class-name="action-column" width="300" fixed="right"><template #default="{ row }"><el-button text type="primary" @click="showDetail(row)">详情</el-button><el-button v-if="row.status === 20" text type="primary" @click="confirm(row)">接单</el-button><el-button v-if="row.status === 20" text type="danger" @click="reject(row)">拒单</el-button><el-button v-if="row.status === 30" text type="success" @click="ready(row)">出餐</el-button><el-button v-if="row.status === 10 || row.status === 30" text type="danger" @click="cancel(row)">取消</el-button><span v-if="row.status >= 40 && row.status !== 60 && row.status !== 70" class="muted">{{ row.status === 40 ? '等待核销' : '已完成' }}</span></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev, pager, next, total" @current-change="load" /><el-drawer v-model="drawer" title="订单详情" size="460px"><div v-loading="detailLoading"><template v-if="detail"><div class="detail-grid"><div><span>订单号</span><b>{{ detail.number }}</b></div><div><span>状态</span><b>{{ statusText[detail.status] }}</b></div><div><span>下单时间</span><b>{{ detail.orderTime }}</b></div><div><span>取餐码</span><b>{{ detail.pickupCode }}</b></div><div><span>金额</span><b>¥{{ detail.amount }}</b></div><div><span>备注</span><b>{{ detail.remark || '无' }}</b></div></div><div class="detail-title">餐品明细</div><div v-for="item in detail.orderDetailList" :key="item.id" class="detail-item"><div><strong>{{ item.name }}</strong><span>{{ item.dishFlavor || '' }}</span></div><span>× {{ item.number }}</span><b>¥{{ Number(item.amount).toFixed(2) }}</b></div><div v-if="detail.cancelReason" class="cancel-reason">取消原因：{{ detail.cancelReason }}</div></template></div></el-drawer></div></template>
<style scoped>.order-stats{display:flex;gap:10px;flex-wrap:wrap}.order-stats span{background:#eef7f4;border:1px solid #dce9e4;border-radius:3px;padding:8px 12px;color:#48645f}.order-stats b{font-size:18px;color:#146b5c;margin-left:6px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding-bottom:16px;border-bottom:1px solid #e6ece9}.detail-grid span,.detail-grid b{display:block}.detail-grid span{font-size:11px;color:#87938f}.detail-grid b{font-size:12px;color:#334842;margin-top:4px;word-break:break-all}.detail-title{margin:18px 0 8px;font-size:14px;font-weight:700}.detail-item{display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid #edf0ee}.detail-item div{flex:1}.detail-item strong,.detail-item span{display:block}.detail-item div span{font-size:11px;color:#87938f;margin-top:3px}.detail-item>span{font-size:12px;color:#71807b}.detail-item b{font-size:12px;color:#a35d31}.cancel-reason{margin-top:16px;padding:10px;background:#fcf7f2;border-left:3px solid #b56a35;color:#795139;font-size:12px}
</style>
